-- aexa-frontend#922: AI-suggested-risk lifecycle (dismiss / import tracking).
--
-- New model only -- no changes to any existing table's columns. The two
-- back-relation fields added to Account/Site in this same change (see
-- account.schema.prisma, site.prisma) are virtual on the Prisma side and
-- require no DDL of their own.
--
-- Hand-written rather than generated by `prisma migrate dev`: the shared
-- local dev database this worktree points at already has drift from
-- in-flight sibling PRs (#345/#346/#347) whose migrations aren't in this
-- worktree's prisma/migrations directory yet, and `prisma migrate dev`
-- would have demanded a full `prisma migrate reset` (dropping that shared
-- dev DB) to proceed. This SQL is the exact DDL Prisma would have generated
-- for aiSuggestionState.prisma's model in isolation.

-- CreateEnum
CREATE TYPE "AiSuggestionStatus" AS ENUM ('DISMISSED', 'IMPORTED');

-- CreateTable
CREATE TABLE "AiSuggestionState" (
    "id" TEXT NOT NULL,
    "siteId" TEXT NOT NULL,
    "orgAccountId" TEXT NOT NULL,
    "fingerprint" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "suggestion" JSONB NOT NULL,
    "status" "AiSuggestionStatus" NOT NULL,
    "actedById" TEXT NOT NULL,
    "actedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "AiSuggestionState_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "AiSuggestionState_siteId_fingerprint_key" ON "AiSuggestionState"("siteId", "fingerprint");

-- CreateIndex
CREATE INDEX "AiSuggestionState_orgAccountId_idx" ON "AiSuggestionState"("orgAccountId");

-- CreateIndex
CREATE INDEX "AiSuggestionState_siteId_status_idx" ON "AiSuggestionState"("siteId", "status");

-- AddForeignKey
ALTER TABLE "AiSuggestionState" ADD CONSTRAINT "AiSuggestionState_siteId_fkey" FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE CASCADE ON UPDATE CASCADE;

