ALTER TABLE "AiSuggestionState" ADD CONSTRAINT "AiSuggestionState_orgAccountId_fkey" FOREIGN KEY ("orgAccountId") REFERENCES "Account"("id") ON DELETE CASCADE ON UPDATE CASCADE;
